  "chunks": [
    {
      "chunk_type": "isnad",
      "arabic_text": "وَ فِي رِوَايَةِ الْحَسَنِ بْنِ مَحْبُوبٍ قَالَ:",
      "translations": {
        "en": "And in the narration of al-Hasan ibn Mahbub, he said:"
      }
    },
    {
      "chunk_type": "opening",
      "arabic_text": "«تَقُولُ فِي آخِرِ سَجْدَةٍ مِنْ صَلَاةِ جَعْفَرِ بْنِ أَبِي طَالِبٍ عَلَيْهِ السَّلَامُ:",
      "translations": {
        "en": "“You say in the final sajdah of the salat of Ja‘far ibn Abi Talib (عليه السلام):"
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "يَا مَنْ لَبِسَ الْعِزَّ وَ الْوَقَارَ يَا مَنْ تَعَطَّفَ بِالْمَجْدِ وَ تَكَرَّمَ بِهِ يَا مَنْ لَا يَنْبَغِي التَّسْبِيحُ إِلَّا لَهُ",
      "translations": {
        "en": "O One who has donned might and dignity, O One who has wrapped Himself in glory and is ennobled by it, O One for whom glorification befits none but Him,"
      }
    },
    {
      "chunk_type": "quran_quote",
      "arabic_text": "يَا مَنْ «أَحْصَىٰ كُلَّ شَيْءٍ» عِلْمُهُ",
      "translations": {
        "en": "O One whose knowledge has encompassed and enumerated all things,"
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "يَا ذَا النِّعْمَةِ وَ الطَّوْلِ يَا ذَا الْمَنِّ وَ الْفَضْلِ يَا ذَا الْقُدْرَةِ وَ الْكَرَمِ أَسْأَلُكَ بِمَعَاقِدِ الْعِزِّ مِنْ عَرْشِكَ وَ مُنْتَهَى الرَّحْمَةِ مِنْ كِتَابِكَ وَ بِاسْمِكَ الْأَعْظَمِ الْأَعْلَى وَ كَلِمَاتِكَ التَّامَّاتِ أَنْ تُصَلِّيَ عَلَىٰ مُحَمَّدٍ وَ آلِ مُحَمَّدٍ وَ أَنْ تَفْعَلَ بِي كَذَا وَ كَذَا.",
      "translations": {
        "en": "O Possessor of blessing and abundance, O Possessor of favor and grace, O Possessor of power and generosity, I ask You by the bonds of might from Your Throne, and the utmost mercy from Your Book, and by Your greatest, highest Name, and Your perfect words, to send blessings upon Muhammad and the family of Muhammad, and to do for me such and such.”
      }
    }
  ],
  "translations": {
    "en": {
      "summary": "This hadith transmits a supplication to be recited in the final sajdah of the salat of Ja‘far ibn Abi Talib عليه السلام. It invokes Allah through His majesty, knowledge, mercy, and supreme Name, and teaches the worshipper to send blessings upon Muhammad and the family of Muhammad before asking for personal needs.",
      "seo_question": "What supplication should be recited in the final sajdah of the salat of Ja‘far ibn Abi Talib عليه السلام?",
      "key_terms": {
        "سَجْدَةٍ": "prostration; here, the final sajdah in the prayer",
        "صَلَاةِ": "salat; the ritual prayer being described",
        "الْعِزَّ": "might, honor, and inviolable dignity attributed to Allah",
        "الْوَقَارَ": "dignity, gravity, and majestic composure",
        "عِلْمُهُ": "His knowledge; Allah’s all-encompassing knowledge",
        "عَرْشِكَ": "Your Throne; invoked here as a sign of divine majesty",
        "اسْمِكَ الْأَعْظَمِ الْأَعْلَى": "Your greatest and highest Name; a supreme divine invocation in du'a",
        "كَلِمَاتِكَ التَّامَّاتِ": "Your perfect words; complete and flawless divine words"
      }
    }
  },
